import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int64_t stride,
                                  int64_t padding,
                                  int64_t dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled implicit-GEMM style Conv2d forward implemented with CuTe tensors.
//   M = N_batch * OH * OW   (output spatial positions, flattened)
//   N = C_out               (output channels)
//   K = C_in * KH * KW      (reduction dim, gathered from input on the fly)
// C[M,N] tile per CTA: BM x BN, k-chunks of BK staged in shared memory.

constexpr int BM       = 128;
constexpr int BN       = 96;
constexpr int BK       = 32;
constexpr int THREADS  = 256;
constexpr int TM       = 8;   // rows per thread   (16 row-groups * 8 = 128)
constexpr int TN       = 6;   // cols per thread   (16 col-groups * 6 = 96)
constexpr int SASTEP   = BM + 1; // padded leading dim to kill smem bank conflicts

__global__ void __launch_bounds__(THREADS)
conv2d_cute_kernel(const float* __restrict__ Xp,
                   const float* __restrict__ Wp,
                   const float* __restrict__ Bp,
                   float* __restrict__ Yp,
                   int N_batch, int C_in, int H, int Win,
                   int C_out, int KH, int KW,
                   int stride, int pad, int dilation,
                   int OH, int OW, int M_total)
{
  // Global tensors as CuTe tensors
  auto mX = make_tensor(make_gmem_ptr(Xp),
      make_shape(N_batch, C_in, H, Win),
      make_stride((int64_t)C_in * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));

  auto mW = make_tensor(make_gmem_ptr(Wp),
      make_shape(C_out, C_in, KH, KW),
      make_stride((int64_t)C_in * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Yp),
      make_shape(N_batch, C_out, OH, OW),
      make_stride((int64_t)C_out * OH * OW, (int64_t)OH * OW, (int64_t)OW, Int<1>{}));

  // Shared memory staging (CuTe tensors)
  __shared__ float smemA[BK * SASTEP];          // (BK, BM) padded
  __shared__ float smemB[BK * BN];              // (BK, BN)
  __shared__ int   sRowN[BM];
  __shared__ int   sRowOH[BM];
  __shared__ int   sRowOW[BM];
  __shared__ int   sRowIH[BM];
  __shared__ int   sRowIW[BM];
  __shared__ int   sKC[BK];
  __shared__ int   sKH[BK];
  __shared__ int   sKW[BK];

  auto sA = make_tensor(make_smem_ptr(smemA),
      make_shape(Int<BK>{}, Int<BM>{}),
      make_stride(Int<SASTEP>{}, Int<1>{}));    // sA(kk, row)

  auto sB = make_tensor(make_smem_ptr(smemB),
      make_shape(Int<BK>{}, Int<BN>{}),
      make_stride(Int<BN>{}, Int<1>{}));        // sB(kk, col)

  const int tid     = threadIdx.x;
  const int m_block = blockIdx.x * BM;
  const int n_block = blockIdx.y * BN;

  // ---- Decode the BM flattened output positions handled by this CTA ----
  // m = ((n * OH) + oh) * OW + ow
  for (int r = tid; r < BM; r += THREADS) {
    int m = m_block + r;
    int n = 0, oh = 0, ow = 0;
    if (m < M_total) {
      ow = m % OW;
      int t = m / OW;
      oh = t % OH;
      n  = t / OH;
    }
    sRowN[r]  = n;
    sRowOH[r] = oh;
    sRowOW[r] = ow;
    sRowIH[r] = oh * stride - pad;
    sRowIW[r] = ow * stride - pad;
  }
  __syncthreads();

  // Thread position inside the 16x16 CTA compute grid
  const int tm = tid % 16;
  const int tn = tid / 16;

  float acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i)
    #pragma unroll
    for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;

  const int K_total = C_in * KH * KW;

  for (int k0 = 0; k0 < K_total; k0 += BK) {
    // ---- Decode this chunk of K into (c, kh, kw) ----
    for (int kk = tid; kk < BK; kk += THREADS) {
      int k = k0 + kk;
      int c = 0, kh = 0, kw = 0;
      if (k < K_total) {
        c       = k / (KH * KW);
        int rem = k - c * KH * KW;
        kh      = rem / KW;
        kw      = rem - kh * KW;
      }
      sKC[kk] = c;
      sKH[kk] = kh;
      sKW[kk] = kw;
    }
    __syncthreads();

    // ---- Load A tile (gather from input with padding bounds check) ----
    // Sweep kk fastest so consecutive threads stay on the same output row and
    // reuse nearby input taps; padded sA keeps kk-fast smem stores conflict-free.
    #pragma unroll
    for (int it = 0; it < (BM * BK) / THREADS; ++it) {
      int idx = tid + it * THREADS;
      int kk  = idx % BK;
      int row = idx / BK;
      float v = 0.0f;
      int m   = m_block + row;
      if (m < M_total && (k0 + kk) < K_total) {
        int ih = sRowIH[row] + sKH[kk] * dilation;
        int iw = sRowIW[row] + sKW[kk] * dilation;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          v = mX(sRowN[row], sKC[kk], ih, iw);
        }
      }
      sA(kk, row) = v;
    }

    // ---- Load B tile (filter weights) ----
    for (int idx = tid; idx < BK * BN; idx += THREADS) {
      int n  = idx % BN;
      int kk = idx / BN;
      float v = 0.0f;
      int cg  = n_block + n;
      if (cg < C_out && (k0 + kk) < K_total) {
        v = mW(cg, sKC[kk], sKH[kk], sKW[kk]);
      }
      sB(kk, n) = v;
    }
    __syncthreads();

    // ---- Compute: rank-1 updates over the k-chunk ----
    #pragma unroll
    for (int kk = 0; kk < BK; ++kk) {
      float rA[TM];
      float rB[TN];
      #pragma unroll
      for (int i = 0; i < TM; ++i) rA[i] = sA(kk, tm + i * 16);
      #pragma unroll
      for (int j = 0; j < TN; ++j) rB[j] = sB(kk, tn + j * 16);
      #pragma unroll
      for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
          acc[i][j] += rA[i] * rB[j];
    }
    __syncthreads();
  }

  // ---- Epilogue: bias add + store ----
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int row = tm + i * 16;
    int m   = m_block + row;
    if (m >= M_total) continue;
    int n  = sRowN[row];
    int oh = sRowOH[row];
    int ow = sRowOW[row];
    #pragma unroll
    for (int j = 0; j < TN; ++j) {
      int cg = n_block + tn + j * 16;
      if (cg < C_out) {
        float v = acc[i][j];
        if (Bp != nullptr) v += Bp[cg];
        mY(n, cg, oh, ow) = v;
      }
    }
  }
}

torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int64_t stride,
                                  int64_t padding,
                                  int64_t dilation)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, KH, KW]");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N_batch = x_c.size(0);
  const int64_t C_in    = x_c.size(1);
  const int64_t H       = x_c.size(2);
  const int64_t Win     = x_c.size(3);

  const int64_t C_out = w_c.size(0);
  const int64_t KH    = w_c.size(2);
  const int64_t KW    = w_c.size(3);
  TORCH_CHECK(w_c.size(1) == C_in, "w.size(1) must equal C_in");

  const int64_t OH = (H   + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t OW = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(OH > 0 && OW > 0, "Invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N_batch, C_out, OH, OW}, x_c.options());

  const int64_t M_total = N_batch * OH * OW;

  dim3 block(THREADS);
  dim3 grid((unsigned)((M_total + BM - 1) / BM),
            (unsigned)((C_out  + BN - 1) / BN));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_cute_kernel<<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N_batch, (int)C_in, (int)H, (int)Win,
      (int)C_out, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)OH, (int)OW, (int)M_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.num_classes = num_classes
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11,
                               stride=4, padding=2)
        self._ext = conv2d_ext

    def forward(self, x):
        return self._ext.cute_conv2d_forward(
            x,
            self.conv1.weight,
            self.conv1.bias,
            int(self.conv1.stride[0]),
            int(self.conv1.padding[0]),
            int(self.conv1.dilation[0]),
        )

